method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0 // The input list must not be empty
    ensures |result| == |numbers| // The output list has the same length as the input list
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1]) // Each element in result is the maximum of all elements in numbers up to index i
{
    var maxSoFar := numbers[0];
    var n := |numbers|;

    result := new int[n]; // Create a new array of the same length as numbers

    // Iterate through the input numbers
    var i := 0;
    while i < n
        invariant 0 <= i <= n // i is always within bounds
        invariant forall j :: 0 <= j < i ==> result[j] == Max(numbers[0..j+1]) // Maintain the correctness of the rolling max
    {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i]; // Update maxSoFar if the current number is greater
        }
        result[i] := maxSoFar; // Set the rolling max for the current position
        i := i + 1; // Move to the next index
    }
}
